1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Todos</title>
7	<style>
8	  * { box-sizing: border-box; }
9	  body {
10	    margin: 0;
11	    padding: 2rem 1rem;
12	    font: 16px/1.4 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
13	    background: #f5f5f4;
14	    color: #1c1917;
15	  }
16	  main { max-width: 32rem; margin: 0 auto; }
17	  h1 { margin: 0 0 1rem; font-size: 1.5rem; }
18	  form { display: flex; gap: 0.5rem; }
19	  input[type="text"], input[type="search"] {
20	    flex: 1;
21	    min-width: 0;
22	    padding: 0.6rem 0.75rem;
23	    font: inherit;
24	    border: 1px solid #d6d3d1;
25	    border-radius: 6px;
26	    background: #fff;
27	  }
28	  button {
29	    padding: 0.6rem 1rem;
30	    font: inherit;
31	    border: 0;
32	    border-radius: 6px;
33	    background: #1c1917;
34	    color: #fff;
35	    cursor: pointer;
36	  }
37	  ul { list-style: none; margin: 1rem 0 0; padding: 0; }
38	  li {
39	    display: flex;
40	    align-items: center;
41	    gap: 0.5rem;
42	    padding: 0.6rem 0.75rem;
43	    margin-bottom: 0.5rem;
44	    background: #fff;
45	    border: 1px solid #e7e5e4;
46	    border-radius: 6px;
47	  }
48	  li span { flex: 1; overflow-wrap: anywhere; }
49	  li button { background: transparent; color: #b91c1c; padding: 0.25rem 0.5rem; }
50	  li button:hover { background: #fee2e2; }
51	  li input[type="checkbox"] { width: 1.1rem; height: 1.1rem; margin: 0; cursor: pointer; }
52	  li[data-completed="true"] span { color: #a8a29e; text-decoration: line-through; }
53	  input[type="date"], select {
54	    padding: 0.5rem;
55	    font: inherit;
56	    border: 1px solid #d6d3d1;
57	    border-radius: 6px;
58	    background: #fff;
59	  }
60	  li .due { flex: none; font-size: 0.85rem; color: #57534e; }
61	  li[data-overdue="true"] { border-color: #fca5a5; background: #fef2f2; }
62	  li[data-overdue="true"] .due { color: #b91c1c; font-weight: 600; }
63	  /* [REQ-006] Priority shown as plain text, no colour, so only overdue is highlighted. */
64	  li .priority { flex: none; font-size: 0.85rem; color: #57534e; }
65	  /* [REQ-007] */
66	  .search { display: block; width: 100%; margin-top: 1rem; }
67	  li input.edit { padding: 0.25rem 0.5rem; }
68	  .filters { display: flex; gap: 0.5rem; margin-top: 1rem; }
69	  .filters button { background: transparent; color: #1c1917; border: 1px solid #d6d3d1; padding: 0.35rem 0.75rem; }
70	  .filters button[aria-pressed="true"] { background: #1c1917; color: #fff; border-color: #1c1917; }
71	  /* [REQ-009] */
72	  .bulk { display: flex; gap: 0.5rem; margin-top: 0.5rem; }
73	  .bulk button { background: transparent; color: #1c1917; border: 1px solid #d6d3d1; padding: 0.35rem 0.75rem; }
74	</style>
75	</head>
76	<body>
77	<main>
78	  <h1>Todos</h1>
79	  <form id="todo-form">
80	    <input type="text" data-testid="todo-input" placeholder="What needs doing?" autocomplete="off" aria-label="New todo">
81	    <input type="date" data-testid="todo-due" aria-label="Due date (optional)">
82	    <select data-testid="todo-priority" aria-label="Priority">
83	      <option value="low">Low</option>
84	      <option value="med" selected>Med</option>
85	      <option value="high">High</option>
86	    </select>
87	    <button type="submit" data-testid="todo-add">Add</button>
88	  </form>
89	  <input type="search" class="search" data-testid="search-input" placeholder="Search todos" autocomplete="off" aria-label="Search todos">
90	  <div class="filters" role="group" aria-label="Filter todos">
91	    <button type="button" data-testid="filter-all" data-filter="all" aria-pressed="true">All</button>
92	    <button type="button" data-testid="filter-active" data-filter="active" aria-pressed="false">Active</button>
93	    <button type="button" data-testid="filter-completed" data-filter="completed" aria-pressed="false">Completed</button>
94	  </div>
95	  <div class="bulk" role="group" aria-label="Bulk actions">
96	    <button type="button" data-testid="bulk-mark-all">Mark all complete</button>
97	    <button type="button" data-testid="bulk-clear-completed">Clear completed</button>
98	  </div>
99	  <ul data-testid="todo-list"></ul>
100	</main>
101	<script>
102	(function () {
103	  var STORAGE_KEY = 'todos';
104	  var form = document.getElementById('todo-form');
105	  var input = document.querySelector('[data-testid="todo-input"]');
106	  var list = document.querySelector('[data-testid="todo-list"]');
107	  var dueInput = document.querySelector('[data-testid="todo-due"]');
108	  var priorityInput = document.querySelector('[data-testid="todo-priority"]');
109	  var searchInput = document.querySelector('[data-testid="search-input"]');
110	
111	  // [REQ-001]
112	  function makeId() {
113	    if (window.crypto && typeof window.crypto.randomUUID === 'function') {
114	      return window.crypto.randomUUID();
115	    }
116	    return Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 10);
117	  }
118	
119	  // [REQ-001]
120	  function loadTodos() {
121	    try {
122	      var parsed = JSON.parse(localStorage.getItem(STORAGE_KEY));
123	      return Array.isArray(parsed) ? parsed : [];
124	    } catch (e) {
125	      return [];
126	    }
127	  }
128	
129	  // [REQ-001]
130	  function saveTodos() {
131	    try {
132	      localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
133	    } catch (e) {}
134	  }
135	
136	  var todos = loadTodos();
137	  var filter = 'all';
138	  var filterButtons = document.querySelectorAll('[data-filter]');
139	  var search = '';        // [REQ-007]
140	  var editingId = null;   // [REQ-007] id of the todo whose text is being edited
141	  var editDraft = '';
142	  var rendering = false;  // [REQ-007] ignore blur caused by render removing the field
143	
144	  // [REQ-002] Active todos first, then completed.
145	  // [REQ-005] Within each group: high, then med, then low; same priority keeps insertion order.
146	  function orderedTodos() {
147	    var result = [];
148	    [false, true].forEach(function (completed) {
149	      ['high', 'med', 'low'].forEach(function (p) {
150	        todos.forEach(function (t) {
151	          if (!!t.completed === completed && normalizePriority(t.priority) === p) result.push(t);
152	        });
153	      });
154	    });
155	    return result;
156	  }
157	
158	  // [REQ-003] Today's LOCAL calendar date as YYYY-MM-DD (never via UTC).
159	  function todayLocal() {
160	    var d = new Date();
161	    var m = d.getMonth() + 1;
162	    var day = d.getDate();
163	    return d.getFullYear() + '-' + (m < 10 ? '0' : '') + m + '-' + (day < 10 ? '0' : '') + day;
164	  }
165	
166	  // [REQ-003] Accept only a plain YYYY-MM-DD string; anything else means no due date.
167	  function normalizeDue(value) {
168	    return typeof value === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(value) ? value : '';
169	  }
170	
171	  // [REQ-003] Overdue = due date strictly before today's local date. Date-only string compare.
172	  function isOverdue(todo, today) {
173	    var due = normalizeDue(todo.due);
174	    return due !== '' && due < today;
175	  }
176	
177	  // [REQ-004] Only low, med or high; anything else (including older todos) is med.
178	  function normalizePriority(value) {
179	    return value === 'low' || value === 'high' ? value : 'med';
180	  }
181	
182	  // [REQ-002]
183	  function isVisible(todo) {
184	    if (filter === 'active') return !todo.completed;
185	    if (filter === 'completed') return !!todo.completed;
186	    return true;
187	  }
188	
189	  // [REQ-007] Case-insensitive substring match; combines with the filter in render.
190	  function matchesSearch(todo) {
191	    return String(todo.text).toLowerCase().indexOf(search.toLowerCase()) !== -1;
192	  }
193	
194	  // [REQ-001]
195	  function render() {
196	    rendering = true;
197	    try { renderList(); } finally { rendering = false; }
198	  }
199	
200	  function renderList() {
201	    list.textContent = '';
202	    filterButtons.forEach(function (btn) {
203	      btn.setAttribute('aria-pressed', String(btn.getAttribute('data-filter') === filter));
204	    });
205	    var today = todayLocal();
206	    orderedTodos().filter(function (t) { return isVisible(t) && matchesSearch(t); }).forEach(function (todo) {
207	      var li = document.createElement('li');
208	      li.setAttribute('data-testid', 'todo-item');
209	      li.setAttribute('data-id', todo.id);
210	      li.setAttribute('data-completed', String(!!todo.completed));
211	      li.setAttribute('data-overdue', String(isOverdue(todo, today)));
212	      li.setAttribute('data-priority', normalizePriority(todo.priority)); // [REQ-004]
213	
214	      var toggle = document.createElement('input');
215	      toggle.type = 'checkbox';
216	      toggle.setAttribute('data-testid', 'todo-toggle');
217	      toggle.setAttribute('aria-label', 'Mark complete');
218	      toggle.checked = !!todo.completed;
219	      toggle.addEventListener('change', function () { toggleTodo(todo.id); });
220	      li.appendChild(toggle);
221	
222	      var text;
223	      if (todo.id === editingId) {
224	        // [REQ-007] Enter or blur commits, Escape cancels.
225	        text = document.createElement('input');
226	        text.type = 'text';
227	        text.className = 'edit';
228	        text.setAttribute('data-testid', 'todo-edit-input');
229	        text.setAttribute('aria-label', 'Edit todo');
230	        text.value = editDraft;
231	        text.addEventListener('input', function () { editDraft = text.value; });
232	        text.addEventListener('keydown', function (e) {
233	          if (e.key === 'Enter') { e.preventDefault(); commitEdit(); }
234	          else if (e.key === 'Escape') { e.preventDefault(); cancelEdit(); }
235	        });
236	        text.addEventListener('blur', function () { if (!rendering) commitEdit(); });
237	      } else {
238	        text = document.createElement('span');
239	        text.setAttribute('data-testid', 'todo-text');
240	        text.textContent = todo.text;
241	        text.addEventListener('dblclick', function () { startEdit(todo.id); }); // [REQ-007]
242	      }
243	
244	      var del = document.createElement('button');
245	      del.type = 'button';
246	      del.setAttribute('data-testid', 'todo-delete');
247	      del.setAttribute('aria-label', 'Delete todo');
248	      del.textContent = 'Delete';
249	      del.addEventListener('click', function () { deleteTodo(todo.id); });
250	
251	      li.appendChild(text);
252	
253	      // [REQ-006] Priority as an uncoloured text label.
254	      var priorityEl = document.createElement('span');
255	      priorityEl.className = 'priority';
256	      priorityEl.textContent = { low: 'Low', med: 'Med', high: 'High' }[normalizePriority(todo.priority)];
257	      li.appendChild(priorityEl);
258	
259	      // [REQ-003] Show the stored string as-is so no timezone shift can occur.
260	      var due = normalizeDue(todo.due);
261	      if (due) {
262	        var dueEl = document.createElement('span');
263	        dueEl.className = 'due';
264	        dueEl.setAttribute('data-testid', 'todo-due-date');
265	        dueEl.textContent = 'Due ' + due;
266	        li.appendChild(dueEl);
267	      }
268	
269	      li.appendChild(del);
270	      list.appendChild(li);
271	    });
272	  }
273	
274	  // [REQ-001]
275	  function addTodo(text, due, priority) {
276	    text = text.trim();
277	    if (!text) return;
278	    // [REQ-003] due is optional, stored as a YYYY-MM-DD string or ''.
279	    todos.push({ id: makeId(), text: text, createdAt: Date.now(), completed: false, due: normalizeDue(due), priority: normalizePriority(priority) }); // [REQ-004]
280	    saveTodos();
281	    render();
282	  }
283	
284	  // [REQ-002]
285	  function toggleTodo(id) {
286	    todos.forEach(function (t) {
287	      if (t.id === id) t.completed = !t.completed;
288	    });
289	    saveTodos();
290	    render();
291	  }
292	
293	  // [REQ-007]
294	  function startEdit(id) {
295	    todos.forEach(function (t) {
296	      if (t.id === id) { editingId = id; editDraft = t.text; }
297	    });
298	    render();
299	    var field = list.querySelector('[data-testid="todo-edit-input"]');
300	    if (field) {
301	      field.focus();
302	      field.setSelectionRange(field.value.length, field.value.length);
303	    }
304	  }
305	
306	  // [REQ-007] Blank text keeps the old text instead of deleting the todo.
307	  function commitEdit() {
308	    if (editingId === null) return;
309	    var id = editingId;
310	    var value = editDraft.trim();
311	    editingId = null;
312	    if (value) {
313	      todos.forEach(function (t) { if (t.id === id) t.text = value; });
314	      saveTodos();
315	    }
316	    render();
317	  }
318	
319	  // [REQ-007]
320	  function cancelEdit() {
321	    editingId = null;
322	    render();
323	  }
324	
325	  // [REQ-002]
326	  function setFilter(value) {
327	    filter = value;
328	    render();
329	  }
330	
331	  filterButtons.forEach(function (btn) {
332	    btn.addEventListener('click', function () { setFilter(btn.getAttribute('data-filter')); });
333	  });
334	
335	  // [REQ-007]
336	  searchInput.addEventListener('input', function () {
337	    search = searchInput.value;
338	    render();
339	  });
340	
341	  // [REQ-001]
342	  function deleteTodo(id) {
343	    todos = todos.filter(function (t) { return t.id !== id; });
344	    saveTodos();
345	    render();
346	  }
347	
348	  // [REQ-009] Mutates in place; orderedTodos re-derives grouping and priority order, and the array keeps insertion order.
349	  function markAllComplete() {
350	    todos.forEach(function (t) { t.completed = true; });
351	    saveTodos();
352	    render();
353	  }
354	
355	  // [REQ-009]
356	  function clearCompleted() {
357	    todos = todos.filter(function (t) { return !t.completed; });
358	    saveTodos();
359	    render();
360	  }
361	
362	  document.querySelector('[data-testid="bulk-mark-all"]').addEventListener('click', markAllComplete);
363	  document.querySelector('[data-testid="bulk-clear-completed"]').addEventListener('click', clearCompleted);
364	
365	  form.addEventListener('submit', function (e) {
366	    e.preventDefault();
367	    addTodo(input.value, dueInput.value, priorityInput.value);
368	    input.value = '';
369	    dueInput.value = '';
370	    priorityInput.value = 'med';
371	    input.focus();
372	  });
373	
374	  // [REQ-003] Refresh overdue state when the page returns after the date may have changed.
375	  document.addEventListener('visibilitychange', function () {
376	    if (!document.hidden) render();
377	  });
378	
379	  render();
380	})();
381	</script>
382	</body>
383	</html>
