// [REQ-010] Enter in todo-input adds via the form's native submit; Escape cancels an edit in the edit field's keydown handler.
// [REQ-010] "/" focuses search unless the user is typing in a field.
function isTypingField(el) {
  if (!el) return false;
  if (el.isContentEditable || el.tagName === 'TEXTAREA' || el.tagName === 'SELECT') return true;
  return el.tagName === 'INPUT' && !/^(checkbox|radio|button|submit|reset)$/.test(el.type);
}

document.addEventListener('keydown', function (e) {
  if (e.key !== '/' || e.ctrlKey || e.metaKey || e.altKey || e.defaultPrevented) return;
  if (isTypingField(document.activeElement)) return;
  e.preventDefault();
  searchInput.focus();
});

// [REQ-003] Refresh overdue state

